tool_input.command:
$login = Invoke-WebRequest -Uri '{{ov_privacy:default:viking://~/privacy/credential/nacos-taicang-dev#/values/base_url}}v1/auth/login' -Method Post -ContentType 'application/x-www-form-urlencoded' -Body 'username=nacos&password={{ov_privacy:default:viking://~/privacy/credential/nacos-taicang-dev#/values/password}}' -SkipHttpErrorCheck -TimeoutSec 15
$token = [string](($login.Content | ConvertFrom-Json -ErrorAction Stop).accessToken)
$uri = '{{ov_privacy:default:viking://~/privacy/credential/nacos-taicang-dev#/values/base_url}}v1/cs/configs?dataId=zhishu-gateway-dev.yml&group=DEFAULT_GROUP&tenant=suzhou-taicang-wuguan&accessToken=' + [uri]::EscapeDataString($token)
$text = [string](Invoke-WebRequest -Uri $uri -Method Get -SkipHttpErrorCheck -TimeoutSec 15).Content
'GATEWAY_CONFIG_LENGTH=' + $text.Length
$lines = $text -split "`r?`n"
$inRoutes = $false
$baseIndent = 0
foreach ($line in $lines) {
  if ($line -match '^(\s*)routes\s*:') { $inRoutes = $true; $baseIndent = $Matches[1].Length; continue }
  if ($inRoutes -and $line -match '^(\s*)(id|uri|predicates)\s*:\s*(.*)$') { 'ROUTE ' + $Matches[2] + '=' + $Matches[3].Trim() }
}
